  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "KNI-272 given as an oral capsule post-prandially at 6.6 mg/kg had absolute bioavailability 36.40% in patients, directly supporting F ≥ 20% under fed conditions."
    },
    {
      "card_ids": ["C08"],
      "claim": "Propranolol absolute bioavailability was 30–35% in humans after 160 mg oral tablets versus IV, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C14"],
      "claim": "Diacetolol absolute bioavailability was 0.426 ± 0.068 after an 800 mg oral dose versus IV in healthy subjects, supporting F ≥ 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All high-transfer molecule-level evidence supports absolute oral bioavailability above 20%, with adult values mostly 25–90%; sub-threshold records are less direct or altered-condition and do not overturn the positive direction.",
  "evidence_gaps": [
    "Most evidence molecules lack explicit fed-state conditions; direct post-prandial evidence is limited to KNI-272 (C35), though C16 indicates no appreciable fasting/post-prandial difference.",
    "Sub-threshold records C24 (calculated propranolol extent_f 0.17) and C05 (pediatric KNI-272 with Ora-Plus, 12%) are less direct or altered-condition and are outweighed by absolute adult measurements."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C35", "C08", "C14"],
  "revision_action": "initial",
  "supportive_card_ids": ["C35", "C08", "C14"]
}

